CREATE TABLE sedes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(140) NOT NULL,distrito VARCHAR(120) NOT NULL);
CREATE TABLE cursos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(180) NOT NULL,especialidad_requerida VARCHAR(120) NOT NULL,horas_semanales INT NOT NULL);
CREATE TABLE docentes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombres VARCHAR(120) NOT NULL,apellidos VARCHAR(120) NOT NULL,especialidad VARCHAR(120) NOT NULL,modalidad_tiempo_parcial BOOLEAN NOT NULL,max_horas_semanales INT NOT NULL);
CREATE TABLE disponibilidades_docente(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,docente_id BIGINT NOT NULL REFERENCES docentes(id),dia_semana VARCHAR(20) NOT NULL,hora_inicio TIME NOT NULL,hora_fin TIME NOT NULL,sede_id BIGINT NOT NULL REFERENCES sedes(id));
CREATE TABLE cargas_academicas(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ciclo_academico VARCHAR(20) NOT NULL,docente_id BIGINT NOT NULL REFERENCES docentes(id),curso_id BIGINT NOT NULL REFERENCES cursos(id),seccion VARCHAR(20) NOT NULL,sede_id BIGINT NOT NULL REFERENCES sedes(id),dia_semana VARCHAR(20) NOT NULL,hora_inicio TIME NOT NULL,hora_fin TIME NOT NULL,estado VARCHAR(20) NOT NULL);
CREATE INDEX idx_carga_docente_ciclo_dia ON cargas_academicas(docente_id,ciclo_academico,dia_semana);
